import { DIAGNOSTIC_CODES, RETIRED_CODES } from "@dustwright/core";
import { RULES } from "./rules/index.js";

const STAGE: Record<string, string> = {
  "1": "1 (structure)",
  "2": "2 (placement and wiring)",
  "3": "3 (simulation)",
  export: "export",
};

/** Renders `docs/diagnostics.md` from the code catalogue and the rule registry, so the docs cannot drift. */
export function renderDiagnosticsDoc(): string {
  const ruleCodes = new Set(RULES.map((r) => r.code));
  const lines = [
    "# Diagnostics",
    "",
    "<!-- GENERATED by `pnpm docs:gen` from packages/core/src/diagnostics.ts and packages/validator/src/rules. Do not edit. -->",
    "",
    "Every diagnostic has `code`, `severity` and `message`, plus `pos` (the cell to blame) or `path` (a JSON",
    "Pointer for schema-level findings), optional `related` positions, and a `hint` naming the fix. Stages run in",
    "order; a later stage runs only when earlier stages found no errors. At most 200 diagnostics are reported (the",
    "200th is an E013 saying the rest were omitted). E009 belongs to stage 2 but is detected while parsing, so it is",
    "reported alongside the stage 1 errors.",
    "",
    "| Code | Severity | Stage | Checked by | Meaning | Fix |",
    "| --- | --- | --- | --- | --- | --- |",
  ];
  const editions = (code: string) => RULES.find((r) => r.code === code)?.editions ?? [];
  for (const d of DIAGNOSTIC_CODES) {
    const only = editions(d.code).length === 1 ? ` (${editions(d.code)[0]} only)` : "";
    const by = RETIRED_CODES.includes(d.code)
      ? "retired"
      : ruleCodes.has(d.code)
        ? `validator rule${only}`
        : d.stage === "export"
          ? "exporter"
          : d.stage === 3
            ? "simulator"
            : "parser";
    lines.push(
      `| ${d.code} | ${d.severity} | ${STAGE[String(d.stage)]} | ${by} | ${d.summary} | ${d.hint} |`,
    );
  }
  return `${lines.join("\n")}\n`;
}
